async function* batches(values, size) {
  let batch = [];
  for await (const value of values) {
    batch.push(value);
    if (batch.length === size) {
      yield batch;
      batch = [];
    }
  }
  if (batch.length) yield batch;
}

for await (const batch of batches([1, 2, 3, 4, 5], 2)) {
